def apply_ops(box, ops):
    for op in ops:
        full = os.path.join(box, op.get("path", ""))
        kind = op["op"]
        if kind == "write":
            os.makedirs(os.path.dirname(full), exist_ok=True)
            with open(full, "wb") as f:
                f.write(op.get("c", "").encode("utf-8"))
            if "m" in op:
                os.utime(full, (op["m"], op["m"]))
        elif kind == "touch":
            os.utime(full, (op["m"], op["m"]))
        elif kind == "sleep":
            time.sleep(op["s"])
        elif kind == "touchall":
