            except UnicodeDecodeError:
                ent = {"t": "f", "b": base64.b64encode(raw).decode()}
            if gz:
                ent["gz"] = True
            if r in sorted_paths and "c" in ent:
                ent["c"] = "\n".join(sorted(ent["c"].split("\n")))
            if os.access(p, os.X_OK):
                ent["x"] = True
            if r in mtimes:
