        if se == "empty" and r["stderr"].strip():
            problems.append(f"{tag}: unexpected output on stderr: {r['stderr'].strip().splitlines()[0][:120]}")
        if se == "nonempty" and not r["stderr"].strip():
            problems.append(f"{tag}: expected a message on stderr")
